def evaluate_postfix(expression: str) -> float:
    """Evaluate a postfix (Reverse Polish Notation) expression.

    Supports operators +, -, *, /, //, %, ** and integer/float operands
    separated by whitespace.

    Args:
        expression: A postfix expression string, e.g. "3 4 + 2 *"

    Returns:
        The numeric result of evaluating the expression.

    Raises:
        ValueError: If the expression is malformed (wrong number of operands/operators).
        ZeroDivisionError: On division by zero.
    """
    tokens = expression.split()
    stack: list[float] = []
    operators = {"+", "-", "*", "/", "//", "%", "**"}

    for token in tokens:
        if token in operators:
            if len(stack) < 2:
                raise ValueError(f"Not enough operands for operator '{token}'")
            b = stack.pop()
            a = stack.pop()
            if token == "+":
                result = a + b
            elif token == "-":
                result = a - b
            elif token == "*":
                result = a * b
            elif token == "/":
                result = a / b
            elif token == "//":
                result = a // b
            elif token == "%":
                result = a % b
            elif token == "**":
                result = a ** b
            stack.append(result)
        else:
            try:
                stack.append(float(token))
            except ValueError:
                raise ValueError(f"Invalid token: '{token}'")

    if len(stack) != 1:
        raise ValueError("Malformed expression: too many operands")

    return stack[0]


