import pytest


class TestBasicArithmetic:
    def test_addition(self):
        assert evaluate_postfix("3 4 +") == 7.0

    def test_subtraction(self):
        assert evaluate_postfix("10 3 -") == 7.0

    def test_multiplication(self):
        assert evaluate_postfix("5 6 *") == 30.0

    def test_division(self):
        assert evaluate_postfix("20 4 /") == 5.0

    def test_floor_division(self):
        assert evaluate_postfix("7 2 //") == 3.0

    def test_modulo(self):
        assert evaluate_postfix("10 3 %") == 1.0

    def test_exponentiation(self):
        assert evaluate_postfix("2 10 **") == 1024.0


class TestCompoundExpressions:
    def test_add_then_multiply(self):
        # (3 + 4) * 2 = 14
        assert evaluate_postfix("3 4 + 2 *") == 14.0

    def test_complex_expression(self):
        # (5 + 3) * (10 - 2) = 64
        assert evaluate_postfix("5 3 + 10 2 - *") == 64.0

    def test_nested_operators(self):
        # ((2 + 3) * 4) - 1 = 19
        assert evaluate_postfix("2 3 + 4 * 1 -") == 19.0

    def test_deeply_nested(self):
        # ((8 / 4) + (6 - 2)) * 3 = 18
        assert evaluate_postfix("8 4 / 6 2 - + 3 *") == 18.0

    def test_chained_exponentiation(self):
        # (2 ** 3) ** 2 = 64
        assert evaluate_postfix("2 3 ** 2 **") == 64.0


class TestEdgeCases:
    def test_single_number(self):
        assert evaluate_postfix("42") == 42.0

    def test_negative_result(self):
        assert evaluate_postfix("3 10 -") == -7.0

    def test_float_operands(self):
        assert evaluate_postfix("3.5 2.5 +") == 6.0

    def test_mixed_int_float(self):
        assert evaluate_postfix("4 2.5 *") == 10.0

    def test_zero_dividend(self):
        assert evaluate_postfix("0 5 /") == 0.0

    def test_result_is_zero(self):
        assert evaluate_postfix("5 5 -") == 0.0

    def test_large_numbers(self):
        assert evaluate_postfix("1000000 1000000 *") == 1e12


class TestErrors:
    def test_division_by_zero(self):
        with pytest.raises(ZeroDivisionError):
            evaluate_postfix("5 0 /")

    def test_too_many_operands(self):
        with pytest.raises(ValueError, match="too many operands"):
            evaluate_postfix("3 4 5 +")

    def test_too_few_operands(self):
        with pytest.raises(ValueError, match="Not enough operands"):
            evaluate_postfix("+")

    def test_invalid_token(self):
        with pytest.raises(ValueError, match="Invalid token"):
            evaluate_postfix("3 abc +")

    def test_empty_expression(self):
        with pytest.raises(ValueError, match="too many operands"):
            evaluate_postfix("")


class TestWhitespace:
    def test_extra_spaces(self):
        assert evaluate_postfix("  3   4  +  ") == 7.0

    def test_tabs(self):
        assert evaluate_postfix("3\t4\t+") == 7.0
